describe('Form Validation - Required Fields Highlighting', () => {
  beforeEach(() => {
    cy.visit('/form');
    cy.get('form').should('be.visible');
  });

  it('should highlight all required fields when submitting empty form', () => {
    cy.get('button[type="submit"]').click();

    cy.get('input[required]').each(($input) => {
      cy.wrap($input)
        .should('have.class', 'error')
        .or('have.attr', 'aria-invalid', 'true');
    });

    cy.get('textarea[required]').each(($textarea) => {
      cy.wrap($textarea)
        .should('have.class', 'error')
        .or('have.attr', 'aria-invalid', 'true');
    });

    cy.get('select[required]').each(($select) => {
      cy.wrap($select)
        .should('have.class', 'error')
        .or('have.attr', 'aria-invalid', 'true');
    });

    cy.get('[role="alert"]').should('be.visible');
  });

  it('should remove highlight when required field is filled', () => {
    cy.get('button[type="submit"]').click();

    cy.get('input[required]').first().should('have.class', 'error');

    cy.get('input[required]').first().type('Valid input');

    cy.get('input[required]').first().should('not.have.class', 'error');
  });

  it('should highlight only empty required fields when some fields are filled', () => {
    cy.get('input[required]').first().type('Filled value');

    cy.get('button[type="submit"]').click();

    cy.get('input[required]').first().should('not.have.class', 'error');

    cy.get('input[required]').eq(1).should('have.class', 'error');
  });

  it('should display error messages for each required field', () => {
    cy.get('button[type="submit"]').click();

    cy.get('input[required]').each(($input) => {
      const fieldName = cy.wrap($input).invoke('attr', 'name');
      cy.get(`[data-error-for="${fieldName}"]`)
        .should('be.visible')
        .and('contain', 'required');
    });
  });

  it('should not highlight optional fields on empty form submission', () => {
    cy.get('button[type="submit"]').click();

    cy.get('input:not([required])').each(($input) => {
      cy.wrap($input).should('not.have.class', 'error');
    });
  });
});
